                        self.gen_addr(target)?; // eax = &target
                        let ta = self.alloc_tmp();
                        self.store_tmp(ta); // save address
                        self.load_rax(&ty)?; // edx:eax = old value
                        let told = self.alloc_tmp();
                        self.store_tmp_i386_i64(told); // save old
