                    let ta = self.alloc_tmp();
                    self.store_tmp(ta); // save address
                    self.load_rax(&ty)?; // rax = old value (load from [rax])
                    let told = self.alloc_tmp();
                    self.store_tmp(told); // save old
                    self.emit_add_rax(step); // rax = new value
                    let tnew = self.alloc_tmp();
                    self.store_tmp(tnew); // save new
                    self.load_tmp(ta);
                    {
                        use crate::codegen::encoder::{Op, RegId};
                        let d = self.wreg(RegId::Rcx);
                        let s = self.wreg(RegId::Rax);
                        self.encode(Op::Mov, &[d, s]);
                    } // mov rcx, rax (address)
                    self.load_tmp(tnew);
                    self.store_at_rcx(&ty)?; // *addr = new
