                // path (libc / Win32 / fn-pointer / direct symbol) for
                // every name that is NOT a class-typed local — gates
                // the O1 88 e2e regression for ordinary calls.
                let recv = Expr::Var(name.clone(), *call_loc);
                if self.local(name).is_ok() && self.has_op_method(&recv, "operator()")? {
                    let mc = self.build_op_method_call(&recv, "operator()", args.clone());
                    return self.gen_expr(&mc);
                }
